WHERE purchase_returns.status >= 0
AND purchase_returns.location_id IN (
SELECT location_id FROM user_locations WHERE user_id= #{userId} GROUP BY location_id
)

    AND purchase_returns.pr_code LIKE CONCAT("%", #{filter.searchText}, "%")


    AND purchase_returns.status = #{filter.status}


    AND purchase_returns.location_id = #{filter.locationId}


    AND purchase_returns.location_group_id = #{filter.warehouseId}


    AND purchase_returns.vendor_id = #{filter.vendorId}


    AND purchase_returns.created_by = #{userId}




            AND purchase_returns.balance > 0


            AND purchase_returns.balance = 0

mapper.select:
SELECT



ORDER BY


        ${filter.orderBy}


        purchase_returns.id DESC


LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(id)
FROM purchase_requests
WHERE is_active = 1 AND name = #{name}
 AND id != #{id}

