UPDATE purchase_returns SET
   balance = #{billReturn.balance},
   total_amount_po = #{billReturn.total},
   modified = NOW(),
   modified_by = #{billReturn.modifiedBy}
WHERE id = #{billReturn.id};

mapper.select:
SELECT 1 AS type, purchase_return_details.purchase_return_id AS billReturnId, purchase_return_details.product_id AS itemId, products.name AS itemName, purchase_return_details.note AS note, purchase_return_details.qty AS qty, IFNULL(purchase_return_details.conversion, 1) AS conversion, purchase_return_details.qty_uom_id AS uomId, uoms.name AS uom, purchase_return_details.expired_date AS expiredDate, products.is_expired_date AS isExpiredDate, purchase_return_details.total_price AS totalCost, purchase_return_details.unit_price AS unitCost FROM purchase_return_details LEFT JOIN purchase_returns ON purchase_return_details.purchase_return_id = purchase_returns.id LEFT JOIN products ON purchase_return_details.product_id = products.id LEFT JOIN uoms ON purchase_return_details.qty_uom_id = uoms.id WHERE purchase_return_details.purchase_return_id = #{purchaseReturnId}
UNION ALL
SELECT 2 AS type, purchase_return_services.purchase_return_id AS billReturnId, purchase_return_services.service_id AS itemId, services.name AS itemName, purchase_return_services.note AS note, purchase_return_services.qty AS qty, 1 AS conversion, NULL AS uomId, NULL AS uom, NULL AS expiredDate, 0 AS isExpiredDate, purchase_return_services.total_price AS totalCost, purchase_return_services.unit_price AS unitCost FROM purchase_return_services LEFT JOIN purchase_returns ON purchase_return_services.purchase_return_id = purchase_returns.id LEFT JOIN services ON purchase_return_services.service_id = services.id WHERE purchase_return_services.purchase_return_id = #{purchaseReturnId}
UNION ALL
SELECT 3 AS type, purchase_return_miscs.purchase_return_id AS billReturnId, NULL AS itemId, purchase_return_miscs.description AS itemName, purchase_return_miscs.note AS note, purchase_return_miscs.qty AS qty, 1 AS conversion, purchase_return_miscs.qty_uom_id AS uomId, uoms.name AS uom, NULL AS expiredDate, 0 AS isExpiredDate, purchase_return_miscs.total_price AS totalCost, purchase_return_miscs.unit_price AS unitCost FROM purchase_return_miscs LEFT JOIN purchase_returns ON purchase_return_miscs.purchase_return_id = purchase_returns.id LEFT JOIN uoms ON purchase_return_miscs.qty_uom_id = uoms.id WHERE purchase_return_miscs.purchase_return_id = #{purchaseReturnId}

